const SEED_KEY = 'batalha_factory_beats_v8'; // v8 to force reload

export async function seedFactoryBeats(): Promise<void> {
  // Runs only once per device
  if (localStorage.getItem(SEED_KEY)) return;

  try {
    let seededCount = 0;
    for (const beat of FACTORY_BEATS) {
      const existing = await db.beats.get(beat.id);
      if (existing) continue;

      // Base URL support for GitHub Pages
      const baseUrl = import.meta.env.BASE_URL || '/';
      const filepath = (baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl) + beat.file;

      const encodedUrl = encodeURI(filepath).replace(/#/g, '%23').replace(/\?/g, '%3F');
      const res = await fetch(encodedUrl);
      if (!res.ok) {
        console.warn(`[BATALHA] Beat não encontrado: ${filepath}`);
        continue;
      }

      const blob = await res.blob();
      await db.beats.add({
        id: beat.id,
        name: beat.name,
        filename: beat.file,
        duration: 0,
        createdAt: Date.now(),
        audioData: blob,
      });
      seededCount++;
    }

    if (seededCount > 0 || FACTORY_BEATS.length === 0) {
      localStorage.setItem(SEED_KEY, '1');
      console.info(`[BATALHA] ${seededCount} beats de fábrica carregados com sucesso.`);
    }
  } catch (err) {
    console.warn('[BATALHA] Seed de beats falhou:', err);
  }
}
